"""Standalone job-seeker portal shell for the canonical career entrypoint."""

from __future__ import annotations


CAREER_PORTAL_NEXT_HTML = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CareerAgent · 校招与全岗位检索</title>
<style>
:root{--ink:#172033;--muted:#64748b;--line:#e5eaf2;--paper:#fff;--brand:#3b5bdb;--light:#f5f7ff;--ok:#11835b;--warn:#b45309}*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:var(--ink);font:14px/1.55 Inter,"Microsoft YaHei",system-ui,sans-serif}.shell{max-width:1460px;margin:auto;padding:28px 24px 48px}header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:22px}.brand{font-size:26px;font-weight:800;letter-spacing:-.8px}.brand span{color:var(--brand)}.sub{color:var(--muted);margin-top:4px}.source{font-size:12px;color:var(--muted);text-align:right}.card{background:var(--paper);border:1px solid var(--line);border-radius:16px;box-shadow:0 5px 18px #1d2b4d08}.search{padding:16px}.filters{display:grid;grid-template-columns:2fr repeat(5,minmax(105px,1fr)) auto;gap:10px}input,select,textarea,button{font:inherit}input,select,textarea{border:1px solid #ced6e3;border-radius:9px;background:#fff;padding:10px;color:var(--ink);width:100%}textarea{min-height:132px;resize:vertical}button{border:0;border-radius:9px;padding:10px 15px;background:var(--brand);color:white;font-weight:700;cursor:pointer}button.secondary{background:var(--light);color:var(--brand);border:1px solid #dbe3ff}button.small{font-size:12px;padding:6px 9px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.stat{padding:12px 14px}.stat b{display:block;font-size:20px}.stat span{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(360px,1.05fr) minmax(440px,1.25fr);gap:16px;align-items:start}.panel{padding:16px}.panel h2{font-size:16px;margin:0 0 10px}.results{display:grid;gap:9px;max-height:700px;overflow:auto;padding-right:3px}.job{padding:13px;border:1px solid var(--line);border-radius:12px;cursor:pointer;transition:.15s}.job:hover,.job.active{border-color:#91a5ff;background:#f7f9ff}.job h3{margin:0;font-size:15px}.meta{color:var(--muted);font-size:12px;margin:4px 0}.excerpt{color:#3f4a5d;font-size:13px;margin:7px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.badge{font-size:11px;border-radius:999px;padding:2px 7px;background:#eef2ff;color:#4056ad}.badge.live{background:#e7f7ef;color:var(--ok)}.badge.history{background:#fff3e5;color:var(--warn)}.empty{color:var(--muted);padding:28px 8px;text-align:center}.detail-title{font-size:21px;font-weight:800;margin:0 0 4px}.detail-company{font-weight:600}.detail-description{white-space:pre-wrap;color:#354156;max-height:280px;overflow:auto;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:12px 0;margin:14px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}.notice{font-size:12px;color:var(--muted);margin:10px 0}.match{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.score{font-size:28px;font-weight:800;color:var(--brand)}.chip{display:inline-block;margin:4px 4px 0 0;padding:3px 7px;border-radius:7px;background:#e8f7ef;color:#087950;font-size:12px}.chip.missing{background:#fff0ed;color:#b44930}.list{padding-left:18px;margin:8px 0}.workspace{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.workspace .panel{min-height:160px}.row{display:flex;gap:8px;align-items:center}.grow{flex:1}.track{font-size:12px;padding:8px 0;border-bottom:1px solid var(--line)}.track:last-child{border:0}.quality{font-size:12px;color:var(--muted);margin-top:8px}.quality.ok{color:var(--ok)}@media(max-width:980px){.filters{grid-template-columns:1fr 1fr}.grid,.workspace{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}header{display:block}.source{text-align:left;margin-top:8px}}
</style></head><body><main class="shell"><header><div><div class="brand">Career<span>Agent</span></div><div class="sub">实时岗位与历史趋势 · 透明匹配 · 本地投递追踪</div></div><div class="source" id="sourceInfo">加载数据质量状态中…</div></header>
<section class="search card"><form id="searchForm" class="filters"><input id="query" placeholder="搜职位、公司或技能，例如：Python / 产品 / 数据分析" autocomplete="off"><select id="scope"><option value="live">当前开放</option><option value="all">当前 + 历史</option><option value="history">仅历史参考</option></select><select id="cycle"><option value="">所有届别</option><option value="2027_autumn">2027 秋招</option><option value="2027_spring">2027 春招</option><option value="2026_autumn">2026 秋招</option><option value="2026_spring">2026 春招</option></select><select id="kind"><option value="">全部类型</option><option value="campus">校招</option><option value="internship">实习</option><option value="experienced">社招</option></select><input id="location" placeholder="地点"><input id="company" placeholder="公司"><select id="semantic"><option value="false">\u4e25\u683c\u5339\u914d</option><option value="true">\u6269\u5c55\u8bed\u4e49\uff08\u53ef\u80fd\u4e0d\u7cbe\u786e\uff09</option></select><button type="submit">搜索岗位</button></form><div class="quality" id="searchNotice">支持语义召回、关键词重排和跨来源去重；结果仍需以官方链接为准。</div></section>
<section class="stats" id="stats"><div class="card stat"><b>—</b><span>可检索岗位</span></div><div class="card stat"><b>—</b><span>当前开放</span></div><div class="card stat"><b>—</b><span>来源健康告警</span></div><div class="card stat"><b>—</b><span>跨来源重复簇</span></div></section>
<section class="grid"><section class="card panel"><h2>岗位结果 <span id="resultCount" class="quality"></span></h2><div id="results" class="results"><div class="empty">输入方向后开始检索，也可以直接搜索全部开放岗位。</div></div></section><section class="card panel"><div id="detail"><div class="empty">选择左侧岗位，查看官方链接、完整 JD 与匹配建议。</div></div><section class="match"><h2>简历匹配与准备建议</h2><textarea id="resume" placeholder="粘贴简历、项目经历或技能清单。仅在本地请求中用于生成本次匹配，不会写入岗位库。"></textarea><div class="actions" style="margin-top:8px"><button id="matchButton" type="button">生成匹配建议</button><button id="subscribeButton" class="secondary" type="button">订阅本次搜索</button></div><div id="matchResult" class="notice">匹配度是技能覆盖与证据准备度提示，不是录用概率。</div></section></section></section>
<section class="workspace"><section class="card panel"><h2>收藏与投递追踪</h2><div id="applications" class="empty">尚未记录投递。选择岗位后可收藏或标记投递阶段。</div></section><section class="card panel"><h2>岗位订阅</h2><div class="row"><input id="subscriptionName" class="grow" placeholder="订阅名称，例如：北京产品校招"><button id="createSubscription" class="small" type="button">保存</button></div><div id="subscriptions" class="empty">保存一个搜索条件，后续可作为每日同步后的筛选模板。</div></section></section>
</main><script>
const el=id=>document.getElementById(id);let selected=null;let lastItems=[];let lastSearchMeta={};const esc=v=>String(v||'');
function stat(label,value){const d=document.createElement('div');d.className='card stat';const b=document.createElement('b');b.textContent=value;const s=document.createElement('span');s.textContent=label;d.append(b,s);return d}
function badge(text,kind=''){const s=document.createElement('span');s.className='badge '+kind;s.textContent=text;return s}
function values(){return{query:el('query').value.trim(),scope:el('scope').value,campus_cycle:el('cycle').value,employment_kind:el('kind').value,location:el('location').value.trim(),company:el('company').value.trim(),expand_semantic:el('semantic').value}}
async function loadQuality(){try{const d=await fetch('/api/career/data-quality').then(r=>r.json());const o=d.overview||{},g=d.governance||{},alerts=(g.source_alerts||[]).length;const live=(o.by_status||{}).open||0;el('stats').replaceChildren(stat('可检索岗位',o.total_jobs||0),stat('当前开放',live),stat('来源健康告警',alerts),stat('跨来源重复簇',g.cross_source_duplicate_clusters||0));el('sourceInfo').textContent=`${Object.keys(o.by_source||{}).length} 个来源 · ${alerts?'存在需关注的同步告警':'来源健康正常'}`;el('searchNotice').textContent=`已检查 ${g.indexed_records_checked||0} 条记录；原始 HTML 描述 ${g.raw_markup_descriptions||0} 条会在界面自动清洗。`}catch{el('sourceInfo').textContent='数据质量接口暂不可用'}}
function draw(items,meta=lastSearchMeta){lastItems=items;lastSearchMeta=meta||{};const box=el('results');box.replaceChildren();const total=Number.isFinite(lastSearchMeta.total_matches)?lastSearchMeta.total_matches:items.length;const exact=lastSearchMeta.all_results===false?'\u8bed\u4e49\u76f8\u5173\u7ed3\u679c':'\u7cbe\u786e\u5339\u914d';el('resultCount').textContent=`\u5171 ${total} \u6761${exact}\uff0c\u5df2\u5c55\u793a ${items.length} \u6761`;if(!items.length){box.innerHTML='<div class="empty">\u672a\u627e\u5230\u5339\u914d\u5c97\u4f4d\u3002\u53ef\u6539\u7528\u66f4\u5177\u4f53\u7684\u5c97\u4f4d\u3001\u516c\u53f8\u6216\u6280\u80fd\u5173\u952e\u8bcd\u3002</div>';return}items.forEach(j=>{const card=document.createElement('article');card.className='job'+(selected&&selected.id===j.id?' active':'');const h=document.createElement('h3');h.textContent=j.title;const m=document.createElement('div');m.className='meta';m.textContent=`${j.company} \u00b7 ${j.location||'\u5730\u70b9\u672a\u62ab\u9732'} \u00b7 ${j.source_name}`;const x=document.createElement('p');x.className='excerpt';x.textContent=j.excerpt;const b=document.createElement('div');b.className='badges';b.append(badge(j.lifecycle_status==='open'?'\u5f53\u524d\u5f00\u653e':(j.lifecycle_status==='unverified'?'\u5f85\u6838\u9a8c':(j.status_reason==='snapshot_not_independently_verified'?'\u5386\u53f2\u5feb\u7167':'\u5386\u53f2\u5f52\u6863')),j.lifecycle_status==='open'?'live':'history'),badge(j.campus_cycle||'\u5c4a\u522b\u672a\u6807\u6ce8'),badge(j.job_group||'other'));if(j.duplicate_count>1)b.append(badge(`\u5408\u5e76 ${j.duplicate_count} \u6761\u5019\u9009`));card.append(h,m,x,b);card.onclick=()=>selectJob(j.id);box.append(card)})}
async function search(){const p=new URLSearchParams(values());el('results').innerHTML='<div class="empty">\u6b63\u5728\u68c0\u7d22\u5339\u914d\u5c97\u4f4d\u2026</div>';try{const r=await fetch('/api/career/search?'+p);const d=await r.json();if(!r.ok)throw Error(d.detail||'\u641c\u7d22\u5931\u8d25');const labels={browse_all:'\u5168\u91cf\u6d4f\u89c8',company_exact:'\u516c\u53f8\u7cbe\u786e\u5339\u914d',title_or_category_exact:'\u5c97\u4f4d/\u7c7b\u522b\u7cbe\u786e\u5339\u914d',full_text_exact:'\u5168\u6587\u7cbe\u786e\u5339\u914d',semantic_expansion:'\u8bed\u4e49\u76f8\u5173\u5339\u914d',no_match:'\u65e0\u5339\u914d'};el('searchNotice').textContent=`${labels[d.match_mode]||'\u68c0\u7d22'}\uff1a${d.total_matches||0} \u6761${d.all_results===false?'\uff08\u8bed\u4e49\u5146\u5e95\u7ed3\u679c\uff09':'\uff0c\u7ed3\u679c\u5df2\u5b8c\u6574\u5c55\u793a'}`;draw(d.items||[],d)}catch(e){el('results').innerHTML='<div class="empty">\u641c\u7d22\u6682\u4e0d\u53ef\u7528\uff1a'+esc(e.message)+'</div>'}}async function selectJob(id){try{const r=await fetch('/api/career/jobs/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw Error(j.detail||'岗位不存在');selected=j;draw(lastItems);const d=el('detail');d.replaceChildren();const title=document.createElement('h1');title.className='detail-title';title.textContent=j.title;const comp=document.createElement('div');comp.className='detail-company';comp.textContent=`${j.company} · ${j.location||'地点未披露'}`;const meta=document.createElement('div');meta.className='meta';meta.textContent=`${j.employment_kind} · ${j.campus_cycle} · ${j.lifecycle_status} · ${j.source_name}`;const desc=document.createElement('div');desc.className='detail-description';desc.textContent=j.description||'该岗位未提供可展示的职位描述。';const actions=document.createElement('div');actions.className='actions';const link=document.createElement('a');link.href=j.source_url;link.target='_blank';link.rel='noreferrer';link.textContent='打开官方岗位页';link.style.cssText='padding:10px 15px;border:1px solid #dbe3ff;border-radius:9px;color:#3b5bdb;font-weight:700;text-decoration:none';const save=document.createElement('button');save.className='secondary';save.textContent='收藏岗位';save.onclick=saveJob;const applied=document.createElement('button');applied.textContent='标记已投递';applied.onclick=()=>track('applied');const interview=document.createElement('button');interview.className='secondary';interview.textContent='标记面试';interview.onclick=()=>track('interview');actions.append(link,save,applied,interview);const n=document.createElement('p');n.className='notice';n.textContent=j.lifecycle_status==='open'?'系统最近同步时标记为开放，投递前仍请在官方页复核。':'该岗位仅作历史/未核验参考，不能据此直接投递。';d.append(title,comp,meta,desc,actions,n)}catch(e){el('detail').innerHTML='<div class="empty">无法读取岗位详情：'+esc(e.message)+'</div>'}}
async function saveJob(){if(!selected)return;await fetch('/api/career/bookmarks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:selected.id})});loadWorkspace()}
async function track(stage){if(!selected)return;await fetch('/api/career/applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:selected.id,stage})});loadWorkspace()}
async function match(){if(!selected){el('matchResult').textContent='请先选择一个岗位。';return}const resume=el('resume').value.trim();if(!resume){el('matchResult').textContent='请先粘贴简历或项目经历。';return}el('matchResult').textContent='正在提取技能和生成准备建议…';try{const r=await fetch('/api/career/match',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:selected.id,resume_text:resume})});const d=await r.json();if(!r.ok)throw Error(d.detail||'匹配失败');const m=d.match;const out=el('matchResult');out.replaceChildren();const score=document.createElement('div');score.className='score';score.textContent=m.score+' / 100';const state=document.createElement('div');state.textContent=m.readiness;const chips=document.createElement('div');(m.matched_skills||[]).forEach(s=>chips.append(badge('已覆盖 '+s,'live')));(m.missing_skills||[]).slice(0,6).forEach(s=>chips.append(badge('待补 '+s,'history')));const ul=document.createElement('ul');ul.className='list';(m.preparation_actions||[]).forEach(a=>{const li=document.createElement('li');li.textContent=a;ul.append(li)});const note=document.createElement('div');note.className='notice';note.textContent=m.boundary_notice;out.append(score,state,chips,ul,note)}catch(e){el('matchResult').textContent='匹配暂不可用：'+esc(e.message)}}
async function loadWorkspace(){try{const [a,s]=await Promise.all([fetch('/api/career/applications').then(r=>r.json()),fetch('/api/career/subscriptions').then(r=>r.json())]);const apps=el('applications');apps.replaceChildren();if(!a.length)apps.textContent='尚未记录投递。选择岗位后可收藏或标记投递阶段。';else a.forEach(x=>{const row=document.createElement('div');row.className='track';row.textContent=`${x.job_title||x.job_id} · ${x.company||''} · ${x.stage}`;apps.append(row)});const subs=el('subscriptions');subs.replaceChildren();if(!s.length)subs.textContent='保存一个搜索条件，后续可作为每日同步后的筛选模板。';else s.forEach(x=>{const row=document.createElement('div');row.className='track';row.textContent=`${x.name}：${x.query||'全部岗位'}`;subs.append(row)})}catch{}}
async function subscription(){const name=el('subscriptionName').value.trim()||'我的岗位订阅';const v=values();const r=await fetch('/api/career/subscriptions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,query:v.query,filters:v})});if(r.ok){el('subscriptionName').value='';loadWorkspace()}}
el('searchForm').onsubmit=e=>{e.preventDefault();search()};el('matchButton').onclick=match;el('subscribeButton').onclick=subscription;el('createSubscription').onclick=subscription;loadQuality();loadWorkspace();search();
</script></body></html>"""
